import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.DGvnA5EY.js";const s="/workbuddy-guide/assets/01-geo-search.CWQTqy5j.png",q=JSON.parse('{"title":"第 21 章 WorkBuddy 也能做 GEO 专家","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 你听过 SEO（让搜索引擎找到你），但现在越来越多人用 AI 问答来找答案——GEO （Generative Engine Optimization，生成式引擎优化）就是\\"让 AI 在回答时提到你\\"…","frontmatter":{"title":"第 21 章 WorkBuddy 也能做 GEO 专家"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 21 章 WorkBuddy 也能做 GEO 专家/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 21 章 WorkBuddy 也能做 GEO 专家/index.md","lastUpdated":1791615980000}'),n={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 21 章 WorkBuddy 也能做 GEO 专家/index.md"};function r(l,t,i,h,p,u){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="第-21-章-workbuddy-也能做-geo-专家" tabindex="-1">第 21 章 WorkBuddy 也能做 GEO 专家 <a class="header-anchor" href="#第-21-章-workbuddy-也能做-geo-专家" aria-label="Permalink to &quot;第 21 章 WorkBuddy 也能做 GEO 专家&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>你听过 SEO（让搜索引擎找到你），但现在越来越多人用 AI 问答来找答案——<strong>GEO</strong> （Generative Engine Optimization，生成式引擎优化）就是&quot;让 AI 在回答时提到你&quot;。 这一章讲清楚 GEO 是什么，以及 WorkBuddy 怎么帮你把内容写得更&quot;容易被 AI 引用&quot;。</p><p><img src="'+s+`" alt="一只小黑举着放大镜，放大镜里映出一个 AI 对话框正在引用它的内容" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;GEO&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次-geo-优化要交付什么" tabindex="-1">一、先想清楚：这次 GEO 优化要交付什么 <a class="header-anchor" href="#一、先想清楚-这次-geo-优化要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次 GEO 优化要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>让 AI 在回答相关问题时引用你</td><td>用户问&quot;新手怎么定投&quot;，答案提到我的文章</td></tr><tr><td>受众</td><td>谁会问、哪个 AI 引擎</td><td>理财小白 + 主流问答助手</td></tr><tr><td>材料</td><td>你已有的内容</td><td>一篇定投科普长文</td></tr><tr><td>格式</td><td>优化后的内容形态</td><td>清晰、结构化、有出处的版本</td></tr><tr><td>验收</td><td>怎么判断有效</td><td>反向体检能过、核心观点被准确转述</td></tr></tbody></table><h2 id="二、geo-和-seo-有什么不同" tabindex="-1">二、GEO 和 SEO 有什么不同 <a class="header-anchor" href="#二、geo-和-seo-有什么不同" aria-label="Permalink to &quot;二、GEO 和 SEO 有什么不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>SEO</th><th>GEO</th></tr></thead><tbody><tr><td>目标对象</td><td>搜索引擎（百度/谷歌）</td><td>AI 问答引擎（各类助手）</td></tr><tr><td>你争取的</td><td>搜索排名靠前</td><td>被 AI 在回答里引用</td></tr><tr><td>内容偏好</td><td>关键词、外链、点击率</td><td>清晰、可信、结构化、有出处</td></tr><tr><td>衡量</td><td>排名/流量</td><td>被引用的频率与准确性</td></tr></tbody></table><p>简单说：SEO 是&quot;让人搜得到你&quot;，GEO 是&quot;让 AI 在回答时想起你&quot;。两者不冲突，可以叠加。</p><h2 id="三、先选对-skill-geo-内容优化的组合" tabindex="-1">三、先选对 Skill：GEO 内容优化的组合 <a class="header-anchor" href="#三、先选对-skill-geo-内容优化的组合" aria-label="Permalink to &quot;三、先选对 Skill：GEO 内容优化的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>写作 / 内容生成技能</strong></td><td>改稿、扩写、重写</td><td>把内容改成 AI 友好版</td><td>事实与口吻你把关</td></tr><tr><td><strong>SEO / 内容优化技能</strong></td><td>关键词、结构建议</td><td>兼顾 SEO 与 GEO</td><td>不堆术语</td></tr><tr><td><strong>find-skills</strong></td><td>找更专业的 GEO 技能</td><td>如&quot;内容体检&quot;类</td><td>零成本入口</td></tr></tbody></table><h2 id="四、真实可复制提示词" tabindex="-1">四、真实可复制提示词 <a class="header-anchor" href="#四、真实可复制提示词" aria-label="Permalink to &quot;四、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-让内容更-ai-友好" tabindex="-1">提示词 1｜让内容更&quot;AI 友好&quot; <a class="header-anchor" href="#提示词-1-让内容更-ai-友好" aria-label="Permalink to &quot;提示词 1｜让内容更&quot;AI 友好&quot;&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这篇内容改成更适合被 AI 引用的版本：</span></span>
<span class="line"><span>1）核心观点用一两句清楚概括，放在开头；</span></span>
<span class="line"><span>2）关键事实标注来源（链接或出处名称）；</span></span>
<span class="line"><span>3）结构用小标题 + 分点，避免大段堆字；</span></span>
<span class="line"><span>4）去掉自相矛盾的说法；</span></span>
<span class="line"><span>5）保留我的口语风格，不要变官方腔。</span></span>
<span class="line"><span>输出改写版，并在末尾列出&quot;改动点&quot;。</span></span></code></pre></div><h3 id="提示词-2-反向体检-我会被引用吗" tabindex="-1">提示词 2｜反向体检：我会被引用吗 <a class="header-anchor" href="#提示词-2-反向体检-我会被引用吗" aria-label="Permalink to &quot;提示词 2｜反向体检：我会被引用吗&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设用户问&quot;新手怎么定投&quot;，请基于我的这篇文章判断：</span></span>
<span class="line"><span>它会不会被 AI 当作可靠答案引用？从清晰度、可信度、结构化、有无出处四个角度打分（1-10），</span></span>
<span class="line"><span>并给出具体的修改清单（哪段要重写得更清楚、哪条事实要补出处）。</span></span>
<span class="line"><span>不要替我编数据，只基于原文诊断。</span></span></code></pre></div><h3 id="提示词-3-批量体检一组内容" tabindex="-1">提示词 3｜批量体检一组内容 <a class="header-anchor" href="#提示词-3-批量体检一组内容" aria-label="Permalink to &quot;提示词 3｜批量体检一组内容&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对我知识库里【理财】标签下的所有文章，各做一次 GEO 体检（提示词 2 的维度），</span></span>
<span class="line"><span>输出一张表：文章、四项得分、最该改的一点。推送到我微信。</span></span></code></pre></div><h2 id="五、执行步骤表" tabindex="-1">五、执行步骤表 <a class="header-anchor" href="#五、执行步骤表" aria-label="Permalink to &quot;五、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>出 AI 友好改写版（提示词 1）</td><td>事实没被改歪、口语还在</td></tr><tr><td>2</td><td>反向体检（提示词 2）</td><td>诊断是否戳中真问题</td></tr><tr><td>3</td><td>你按清单改稿</td><td>出处真实、没编造权威感</td></tr></tbody></table><h2 id="六、零成本-skill-把-geo-体检-固化" tabindex="-1">六、零成本 Skill：把&quot;GEO 体检&quot;固化 <a class="header-anchor" href="#六、零成本-skill-把-geo-体检-固化" aria-label="Permalink to &quot;六、零成本 Skill：把&quot;GEO 体检&quot;固化&quot;">​</a></h2><p>提示词 2 这种&quot;每篇发布前都做&quot;的需求，用 <code>skill-creator</code> 固化成&quot;GEO 体检&quot;技能： 以后丢一篇链接，它按四维打分+修改清单出结果，不用每次写长提示词。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：你的内容从&quot;写得漂亮&quot;升级为&quot;写得清楚、可被 AI 准确转述&quot;，在 AI 问答 时代多一层被看见的机会。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 改写版核心观点清晰、关键事实有出处</li><li>[ ] 反向体检四项得分合理，修改清单你真去执行了</li><li>[ ] 没有为被引用而编造&quot;权威感&quot;或假数据</li></ul><h2 id="八、一个必须记住的坑" tabindex="-1">八、一个必须记住的坑 <a class="header-anchor" href="#八、一个必须记住的坑" aria-label="Permalink to &quot;八、一个必须记住的坑&quot;">​</a></h2><p><strong>别为被引用而编造&quot;权威感&quot;。</strong> GEO 的核心是&quot;真有干货且讲得清&quot;，不是堆术语、假数据。 AI 越来越会识别不可信内容——你骗它，它反而不引你。<strong>务实、标来源、讲人话，才是 长期被引用的根本。</strong></p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>GEO（生成式引擎优化）</strong>：让 AI 问答在回答相关问题时引用你的内容。</p><p><strong>被引用</strong>：你的内容成为 AI 答案里&quot;据称/据 XX&quot;的那条依据。</p><p><strong>结构化</strong>：用小标题、分点、表格把内容组织清楚，AI 更容易抓取和转述。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把&quot;GEO 体检&quot;固化成专属技能。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 用提示词 1 改一篇你已有的内容做 GEO 优化</li><li>[ ] 用提示词 2 给内容打 GEO 体检分并改一版</li><li>[ ] （进阶）用 skill-creator 把&quot;GEO 体检&quot;固化成技能</li><li>[ ] 记住原则：务实 + 标来源 + 讲人话，才是长期被引用的根本</li></ul><hr><p><em>下一篇：第三篇 进阶篇——把案例变成自己的工作系统。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,37)])])}const b=a(n,[["render",r]]);export{q as __pageData,b as default};
